import{z as i,x as A,o as E,c as B,q as n,j as l,D as s,d as e,s as r,S as o,b as p}from"./chunks/framework.C8m1ZpeB.js";const D=JSON.parse('{"title":"pass@k","description":"","frontmatter":{"title":"pass@k","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/pass-at-k.md","filePath":"llm/pass-at-k.md","lastUpdated":1791063341000}'),d={name:"llm/pass-at-k.md"};function k(m,a,h,C,c,_){const t=A("Mermaid");return E(),B("div",null,[a[2]||(a[2]=n('<h1 id="pass-k" tabindex="-1">pass@k <a class="header-anchor" href="#pass-k" aria-label="Permalink to &quot;pass@k&quot;">​</a></h1><div class="epigraph"><p>从 n 个样本里估计「k 次提交至少对一次」的概率。报 pass@1 与 pass@100 而不写 n 和温度，等于没报编码能力。</p><footer>—— Chen 等 Codex / HumanEval 的无偏估计量</footer></div><p><a href="/llm/answer-extraction">上一课</a>把「对」定义成抽取或执行之后的布尔。代码评测的布尔来自单元测试，而且通常允许多样本。<a href="/llm/code-bench">HumanEval</a> 把这个数字写成 pass@\\(k\\)。缺口是：它不是准确率的别名，而是<strong>带预算的覆盖概率</strong>。后课校准默认你会：pass@\\(k\\) 测的是「会不会抽到对的」，不测「知不知道自己对」。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>一次生成（pass@1）惩罚探索：温度 0 的贪婪解码可能卡在一种错解。产品里用户会重试，竞赛里选手会交多次。需要一个随 \\(k\\) 变化的曲线，而不是单点。朴素算法「采 \\(k\\) 次看有没有对的」方差大，且 \\(k\\) 一变就要重跑。Chen 等人给出无偏估计：先采 \\(n\\ge k\\) 个独立样本，计 \\(c\\) 个通过测试，再算组合比。</p><p>温度与 \\(n\\) 是协议的一部分。高温抬 pass@\\(k\\)、打压 pass@1，这是多样性，不是「更大的模型」。把 pass@100 拿去和别人的 pass@1 比，是在比较计算预算。</p><p><span class="marginnote">pass@\\(k\\) 假设样本独立同分布。束搜索或带记忆的重试会破坏假设，估计量偏高。产品重试若看上一次报错，应另报「带反馈的修复率」，不要冒充 pass@\\(k\\)。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>无偏估计（Chen 等）：</p> \\[\\mathrm{pass@}k=\\mathbb{E}\\left[1-\\frac{\\binom{n-c}{k}}{\\binom{n}{k}}\\right], \\]<p>\\(c\\) 为 \\(n\\) 次中通过数；\\(n-c\\lt k\\) 时分子为零，pass@\\(k=1\\)。实现用稳定递推避免大组合数溢出。报告必须写 \\(n,k,\\) 温度, top-\\(p,\\) 是否过滤语法失败。功能正确性以隐藏测试为准；表面相似（BLEU）不是 pass。</p><p><span class="marginnote">数字实例：\\(n=100\\)、\\(c=10\\) 时，\\(k=1\\) 的 pass@1 约为 \\(10/100=0.1\\)；换成 \\(k=10\\)，按公式约 \\(1-\\binom{90}{10}/\\binom{100}{10}\\approx 0.67\\)。同一批 100 个样本，只改提交预算就能从 0.1 报到 0.67——这就是「不写 \\(k\\) 等于没报编码能力」的直接原因。</span></p>',12)),(E(),l(o,null,{default:s(()=>[r(t,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20TD%0A%20%20P%5B%22%E9%A2%98%E7%9B%AE%22%5D%20--%3E%20S%5B%22n%20%E6%AC%A1%E7%8B%AC%E7%AB%8B%E9%87%87%E6%A0%B7%22%5D%0A%20%20S%20--%3E%20T%5B%22%E5%8D%95%E5%85%83%E6%B5%8B%E8%AF%95%22%5D%0A%20%20T%20--%3E%20C%5B%22%E9%80%9A%E8%BF%87%E6%95%B0%20c%22%5D%0A%20%20C%20--%3E%20PK%5B%22%E6%97%A0%E5%81%8F%20pass%40k%22%5D%0A"})]),fallback:s(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=p("h2",{id:"机制",tabindex:"-1"},[e("机制 "),p("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=p("p",null,"生成分布 \\(p_\\theta(y\\mid x)\\) 在正确程序集合上的质量若为 \\(p_{\\mathrm{ok}}\\)，则独立 \\(k\\) 次至少一次成功的概率是 \\(1-(1-p_{\\mathrm{ok}})^k\\)。pass@\\(k\\) 是对这个量的估计。它奖励「分布里有正确质量」的模型，即使众数是错的。这与似然评测相反：似然看众数附近，pass@\\(k\\) 看支撑集。RL 若只优化 pass@1，可能把分布压成单一模式，pass@100 反而掉——要分列。",-1)),(E(),l(o,null,{default:s(()=>[r(t,{id:"mermaid-39",class:"mermaid",graph:"flowchart%20TD%0A%20%20D%5B%22%E7%94%9F%E6%88%90%E5%88%86%E5%B8%83%22%5D%20--%3E%20M%5B%22%E4%BC%97%E6%95%B0%EF%BC%9A%E6%A6%82%E7%8E%87%E6%9C%80%E9%AB%98%E7%9A%84%E9%82%A3%E4%B8%AA%E8%BE%93%E5%87%BA%22%5D%0A%20%20D%20--%3E%20S%5B%22%E6%94%AF%E6%92%91%E9%9B%86%EF%BC%9A%E6%95%A3%E8%90%BD%E5%9C%A8%E5%90%84%E5%A4%84%E7%9A%84%E6%AD%A3%E7%A1%AE%E7%A8%8B%E5%BA%8F%E8%B4%A8%E9%87%8F%20p_ok%22%5D%0A%20%20M%20--%3E%20L%5B%22%E4%BC%BC%E7%84%B6%E8%AF%84%E6%B5%8B%E5%9C%A8%E8%BF%99%E9%87%8C%E6%89%93%E5%88%86%EF%BC%9A%E4%BC%97%E6%95%B0%E9%94%99%E4%BA%86%E5%B0%B1%E4%BD%8E%E5%88%86%22%5D%0A%20%20S%20--%3E%20PK%5B%22pass%40k%20%E5%9C%A8%E8%BF%99%E9%87%8C%E6%89%93%E5%88%86%EF%BC%9Ak%20%E6%AC%A1%E5%86%85%E6%8A%BD%E4%B8%AD%E4%B8%80%E6%AC%A1%E5%B0%B1%20pass%22%5D%0A%20%20PK%20--%3E%20F%5B%22k%20%E8%B6%8A%E5%A4%A7%EF%BC%8C1-(1-p_ok)%5Ek%20%E8%B6%8A%E6%8E%A5%E8%BF%91%201%22%5D%0A%20%20L%20--%3E%20R%5B%22%E5%8F%AA%E4%BC%98%E5%8C%96%20pass%401%20%E4%BC%9A%E5%8E%8B%E6%89%81%E5%88%86%E5%B8%83%EF%BC%8Cpass%40100%20%E5%8F%8D%E8%80%8C%E6%8E%89%22%5D%0A"})]),fallback:s(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=n('<p><span class="marginnote">术语翻译：「支撑集」就是分布概率不为零的那片输出空间；「众数」是概率最高的峰。高峰是错的、但山坡上藏着正确程序时，pass@k 大而似然小——两个指标在给分布的不同部位打分，谁也不取代谁。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>测试覆盖不足时，pass 会把错程序标对。隐藏测试与对抗用例属于基准质量，不是估计量的问题。下一课校准处理的是另一件事：模型给出的置信是否等于 \\(p_{\\mathrm{ok}}\\)。</p><p><span class="marginnote">常见误区：把 pass@100 当成「真实能力」。它隐含用户愿意重试一百次、并付一百倍的推理钱；多数产品只有一次机会，对应的恰恰是被高温抬高之前的 pass@1。正确做法是报整条随 \\(k\\) 变化的曲线，而不是挑一个好看的点。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>pass@\\(k\\) 是带提交预算的覆盖率，必须锁 \\(n\\)、温度与独立采样。</li><li>用 Chen 等的组合无偏估计，不要只跑 \\(k\\) 次。</li><li>它测支撑集里有没有对的，不测校准，也不等于贪婪准确率。</li><li>出处：Chen 等，Evaluating Large Language Models Trained on Code（HumanEval / Codex）。</li></ul>',6))])}const f=i(d,[["render",k]]);export{D as __pageData,f as default};
